'use strict';
const publisherState={data:null,error:null,query:'',corpus:'all',model:'all',page:1};
const publisherName=k=>({magenta_pixie:'Magenta Pixie · publisher PDFs',tracy_kumbera:'Tracy Kumbera · publisher captions'}[k]||human(k));
const decimal=(x,n=4)=>typeof x==='number'&&Number.isFinite(x)?x.toLocaleString('en-US',{maximumFractionDigits:n}):'Unknown';
async function loadPublisher(audit){publisherState.error=null;const path=audit.supplementary_studies?.publisher_texts;if(!path){publisherState.error='No publisher-text study is linked to this snapshot.';return;}try{if(path!=='source-topics.json')throw Error('Unexpected publisher study path.');const response=await fetch(path);if(!response.ok)throw Error('Publisher text data returned HTTP '+response.status);const data=await response.json();if(data.schema_version!==1||!Array.isArray(data.documents)||data.synthetic_fixture_run===true)throw Error('Publisher text data are not an admitted source-backed release.');publisherState.data=data;}catch(e){publisherState.data=null;publisherState.error=e.message;}}
function publisherFigure(id,title){const d=publisherState.data,svg=arr(d.figures).find(f=>f.file===id+'.svg'),others=arr(d.figures).filter(f=>[id+'.png',id+'.pdf'].includes(f.file));if(!svg)return '';return `<figure class="figure"><h3>${esc(title)}</h3><p class="figure-open"><a href="text-figures/${esc(svg.file)}?v=${esc(svg.sha256)}" target="_blank" rel="noopener">Open larger figure</a></p><img loading="lazy" src="text-figures/${esc(svg.file)}?v=${esc(svg.sha256)}" alt="${esc(svg.caption)}"><figcaption>${esc(svg.caption)}<div class="figure-links">${[svg,...others].map(f=>`<a href="text-figures/${esc(f.file)}?v=${esc(f.sha256)}" download>${esc(f.file.split('.').at(-1).toUpperCase())}</a>`).join('')}</div></figcaption></figure>`;}
function publisherDocs(){const q=publisherState.query.toLowerCase();return arr(publisherState.data?.documents).filter(d=>(publisherState.corpus==='all'||d.corpus===publisherState.corpus)&&(publisherState.model==='all'||(publisherState.model==='included'?d.included_in_model===true:d.included_in_model!==true))&&(!q||[d.source_id,d.title,d.source_kind,d.source_format,d.corpus,d.exclusion_reason].join(' ').toLowerCase().includes(q)));}
function publisherTable(){const rows=publisherDocs(),pages=Math.max(1,Math.ceil(rows.length/12));publisherState.page=Math.min(publisherState.page,pages);return `<div class="result-summary publisher-result-summary"><p><strong>${rows.length}</strong> of ${arr(publisherState.data.documents).length} retained publisher publications match. Duplicate publications remain visible; model eligibility is a separate field.</p><button type="button" class="secondary" id="export-publisher">Export filtered publisher metadata</button></div><div class="table-wrap" role="region" tabindex="0" aria-label="Retained publisher text sources"><table class="source-table publisher-table"><thead><tr><th scope="col">Publisher source</th><th scope="col">Source context / format</th><th scope="col">Words / language</th><th scope="col">Model disposition</th></tr></thead><tbody>${rows.slice((publisherState.page-1)*12,publisherState.page*12).map(d=>`<tr><th scope="row"><button type="button" class="source-title" data-publisher-source="${esc(d.source_id)}">${esc(d.title||d.source_id)}</button><small>${esc(d.source_id)}</small></th><td>${esc(publisherName(d.corpus))}<small>${esc(human(d.source_kind))}</small></td><td>${number(d.whitespace_words)}<small>${esc(d.language||'unreported')}</small></td><td>${d.included_in_model===true?'Included model unit':d.model_unit_source_id&&d.model_unit_source_id!==d.source_id?'Exact-text duplicate publication':'Excluded from this fit'}<small>${esc(d.exclusion_reason||'See source metadata for source format and attribution.')}</small></td></tr>`).join('')||'<tr><td colspan="4">No publisher texts match these filters.</td></tr>'}</tbody></table></div><div class="pager publisher-pager"><button class="secondary" type="button" data-publisher-page="${publisherState.page-1}" ${publisherState.page<=1?'disabled':''}>Previous</button><span>Page ${publisherState.page} of ${pages}</span><button class="secondary" type="button" data-publisher-page="${publisherState.page+1}" ${publisherState.page>=pages?'disabled':''}>Next</button></div>`;}
function publisherView(){const d=publisherState.data;if(!d)return `<section id="publisher-texts" class="section" tabindex="-1"><h2>Publisher text analysis.</h2><p class="empty">${esc(publisherState.error||'Publisher text analysis is unavailable.')}</p></section>`;const cov=d.coverage||{},selected=arr(d.clusters?.candidates).find(c=>c.k===d.clusters?.selected_k),pairs=d.lexical?.content?.pair_summary||{},windowPairs=d.lexical?.window_600?.pair_summary||{},neural=d.semantic?.full?.pair_summary||{},names=['magenta_pixie_within','tracy_kumbera_within','between_corpora'];return `<section id="publisher-texts" class="section" tabindex="-1"><div class="section-head"><h2>Two publisher contexts, carefully compared.</h2><p>Magenta Pixie PDF material and Tracy Kumbera RSS-linked caption tracks form a separately fitted study. Publisher/project labels do not establish who speaks in every passage.</p></div><div class="scope-note"><p><strong>Coverage is two publisher contexts, not all included accounts.</strong> The other screened mediums have no text model in this study. One exact caption-byte duplicate is collapsed for fitting; recording identity remains unresolved. Four reference texts and one Portuguese transcript are visible but excluded from the English transcript models.</p><p>The dataset retains captions and extracted PDF text. It does not establish that the corresponding videos or audios were downloaded, nor that every PDF is a human transcript.</p></div><div class="discovery-strip"><div><b>${number(cov.observed_publications)}</b><span>retained publisher publications</span></div><div><b>${number(cov.primary_publications)}</b><span>English transcript publications</span></div><div><b>${number(cov.primary_model_units)}</b><span>deduplicated model units</span></div><div><b>${number(cov.all_publication_words)}</b><span>words across all publications</span></div></div><div class="table-wrap" tabindex="0" role="region" aria-label="Publisher model coverage"><table><thead><tr><th scope="col">Source context</th><th scope="col">Transcript publications</th><th scope="col">Model units</th><th scope="col">Model-unit words</th></tr></thead><tbody>${Object.entries(cov.primary_by_corpus||{}).map(([key,c])=>`<tr><th scope="row">${esc(publisherName(key))}</th><td>${number(c.primary_publications)}</td><td>${number(c.model_units)}</td><td>${number(c.whitespace_words)}</td></tr>`).join('')}</tbody></table></div><div class="section-head publisher-subhead"><h3>Lexical and semantic similarity</h3><p>Full-text TF-IDF, 600-token windows and MiniLM embeddings measure different aspects of language. Cosines are not agreement or accuracy probabilities. Each row retains its dependent-pair denominator.</p></div><div class="table-wrap" tabindex="0" role="region" aria-label="Publisher text similarities"><table><thead><tr><th scope="col">Comparison</th><th scope="col">Document pairs</th><th scope="col">Content TF-IDF cosine</th><th scope="col">600-token cosine</th><th scope="col">MiniLM cosine</th></tr></thead><tbody>${names.map(k=>`<tr><th scope="row">${esc(k==='between_corpora'?'Between publisher contexts':publisherName(k.replace('_within',''))+' · within')}</th><td>${number(pairs[k]?.pairs)}</td><td>${decimal(pairs[k]?.mean)}</td><td>${decimal(windowPairs[k]?.mean)}</td><td>${decimal(neural[k]?.mean)}</td></tr>`).join('')}</tbody></table></div><p class="table-note">${esc(d.semantic?.full?.scope||'Dependent source-text comparisons do not identify common beliefs or claimed entities.')}</p><div class="section-head publisher-subhead"><h3>Exploratory topics and clusters</h3><p>NMF factors describe recurring words. The displayed k=${number(d.clusters?.selected_k)} K-means partition has silhouette ${decimal(selected?.cosine_silhouettes?.[0])}; format and publisher are confounded, so clusters do not establish civilizations or teachings.</p></div><div class="topic-grid">${arr(d.topics?.components).map(t=>`<article class="topic-block"><h3>Factor ${number(t.component)}</h3><div class="chip-list">${arr(t.terms).map(term=>`<span class="term">${esc(term)}</span>`).join('')}</div><p>${Object.entries(t.source_context_means||{}).map(([k,v])=>esc(publisherName(k))+': '+decimal(v,3)).join('; ')}</p></article>`).join('')}</div>${publisherFigure('text-coverage','Corpus size and source format')}${publisherFigure('text-keywords','Keyword groups, equal-unit and pooled rates')}${publisherFigure('text-map','Text projection and exploratory clusters')}${publisherFigure('text-topics','Topic mixtures across source contexts')}${publisherFigure('text-sensitivity','Sensitivity to length and source selection')}<details><summary>Keyword-based extraction and dictionary definitions</summary><p class="table-note">Counts use the declared dictionaries and tokenizer; homonyms, negation, quotations and recognition errors can change meaning. Counts are not validated belief labels.</p><dl class="method-list">${Object.entries(d.keywords?.dictionaries||{}).map(([k,terms])=>`<dt>${esc(human(k))}</dt><dd>${esc(arr(terms).join(', '))}</dd>`).join('')}</dl></details><div class="section-head publisher-subhead"><h3>Questions remain candidates</h3><p>${number(d.qa?.punctuation_candidates)} punctuation candidates span all ${number(d.qa?.documents)} retained publications, not only the model denominator. ${number(d.qa?.verified_questions)} verified questions and ${number(d.qa?.identified_answers)} identified answers are reported. Cue/page units are not diarized speaker turns.</p></div><p class="table-note">${esc(d.qa?.scope)}</p><details><summary>Inspect ${number(arr(d.reading_leads).length)} model-selected reading leads</summary><div class="table-wrap" tabindex="0" role="region" aria-label="Model-selected publisher reading leads"><table class="source-table"><thead><tr><th scope="col">Factor / context</th><th scope="col">Source</th><th scope="col">Cue / page locators</th><th scope="col">Selection scope</th></tr></thead><tbody>${arr(d.reading_leads).map(r=>{const doc=arr(d.documents).find(x=>x.source_id===r.source_id);return `<tr><th scope="row">Factor ${number(r.component)}<small>${esc(publisherName(r.corpus))}</small></th><td><button type="button" class="source-title" data-publisher-source="${esc(r.source_id)}">${esc(doc?.title||r.source_id)}</button></td><td>${esc(arr(r.turn_ids).join(', '))}</td><td>${esc(r.selection)}<small>${number(r.words)} words in selected window</small></td></tr>`;}).join('')}</tbody></table></div></details><div class="section-head publisher-subhead"><h3>Inspect retained publisher records</h3><p>Open a document’s extraction, attribution, duplicate status and source URLs. Full raw texts remain in the private archive.</p></div><div class="toolbar"><label class="search-label">Search publisher titles and records<input id="publisher-query" type="search" value="${esc(publisherState.query)}" placeholder="Title, source ID, format or exclusion"></label><label>Source context<select id="publisher-corpus">${option('all','All publisher contexts',publisherState.corpus)}${Object.keys(cov.primary_by_corpus||{}).map(k=>option(k,publisherName(k),publisherState.corpus)).join('')}</select></label><label>Model disposition<select id="publisher-model">${option('all','All publications',publisherState.model)}${option('included','Included model units',publisherState.model)}${option('excluded','Outside model units',publisherState.model)}</select></label><button id="clear-publisher" type="button" class="secondary">Clear publisher filters</button></div><div id="publisher-results">${publisherTable()}</div><details><summary>Study limitations and transformations</summary><ul class="limits">${arr(d.limitations).map(l=>`<li>${esc(typeof l==='string'?l:JSON.stringify(l))}</li>`).join('')}</ul><pre>${esc(JSON.stringify(d.transformations,null,2))}</pre></details><div class="download-list"><a href="source-topics.json" download>Publisher text analysis JSON</a><a href="../channeling-network/#analysis">Expanded cross-context comparison</a></div></section>`;}
function inspectPublisher(id){const d=arr(publisherState.data?.documents).find(x=>x.source_id===id);if(!d)return;previousFocus=document.activeElement;detail.innerHTML=`<h2 id="channel-title">${esc(d.title||d.source_id)}</h2><p>${esc(publisherName(d.corpus))} · ${esc(human(d.source_kind))}</p><dl class="record-meta"><dt>Source ID</dt><dd>${esc(d.source_id)}</dd><dt>Model disposition</dt><dd>${d.included_in_model===true?'Included primary model unit':'Outside fitted model units'}</dd><dt>Model-unit source ID</dt><dd>${esc(d.model_unit_source_id||'Not assigned')}</dd><dt>Exclusion / duplicate reason</dt><dd>${esc(d.exclusion_reason||'None reported')}</dd><dt>Words</dt><dd>${number(d.whitespace_words)}</dd><dt>Language / basis</dt><dd>${esc(d.language)} · ${esc(d.language_basis)}</dd><dt>Published date</dt><dd>${esc(d.published_at||'Unknown')} · ${esc(d.date_status)}</dd><dt>Speaker roles verified</dt><dd>${d.speaker_roles_verified===true?'Yes':'No'}</dd><dt>Full semantic reading complete</dt><dd>${d.human_semantic_reading_complete===true?'Yes':'No'}</dd><dt>Recording identity</dt><dd>${esc(d.original_session_family_status||'Unresolved')}</dd><dt>Source SHA-256</dt><dd class="hash">${esc(d.source_artifact_sha256)}</dd><dt>Extracted text SHA-256</dt><dd class="hash">${esc(d.text_artifact_sha256)}</dd></dl><p>${link(d.source_url,'Publisher source page')}</p><p>${link(d.download_url,'Publisher text artifact')}</p><p><strong>Project attribution does not assign every utterance to a claimed entity.</strong> ${esc(d.medium_attribution?.scope||'')}</p><h3>Extraction and attribution metadata</h3><pre>${esc(JSON.stringify({claimed_entities:d.claimed_entities,caption_generation_provenance:d.caption_generation_provenance,transcript_generation_provenance:d.transcript_generation_provenance,text_completeness:d.text_completeness},null,2))}</pre>`;dialog.showModal();document.querySelector('#close-channel').focus();}
function updatePublisher(){document.querySelector('#publisher-results').innerHTML=publisherTable();announce(publisherDocs().length+' matching publisher publications.');}
function exportPublisher(){const rows=publisherDocs(),headers=['source_id','title','corpus','source_kind','source_format','language','whitespace_words','included_in_model','model_unit_source_id','exclusion_reason','source_url','download_url','source_artifact_sha256','text_artifact_sha256'],body=[headers,...rows.map(d=>headers.map(k=>d[k]))].map(r=>r.map(csvCell).join(',')).join('\r\n')+'\r\n',url=URL.createObjectURL(new Blob([body],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='publisher-text-source-metadata.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('Exported '+rows.length+' publisher metadata records.');}
app.addEventListener('input',e=>{if(e.target.id==='publisher-query'){publisherState.query=e.target.value;publisherState.page=1;updatePublisher();}});
app.addEventListener('change',e=>{if(e.target.id==='publisher-corpus'||e.target.id==='publisher-model'){publisherState[e.target.id==='publisher-corpus'?'corpus':'model']=e.target.value;publisherState.page=1;updatePublisher();}});
app.addEventListener('click',e=>{const target=e.target.closest('[data-publisher-source]');if(target){inspectPublisher(target.dataset.publisherSource);return;}const page=e.target.closest('[data-publisher-page]');if(page&&!page.disabled){publisherState.page=Number(page.dataset.publisherPage);updatePublisher();(app.querySelector('.publisher-pager button:last-child:not(:disabled)')||app.querySelector('.publisher-pager button:first-child:not(:disabled)'))?.focus();return;}if(e.target.id==='clear-publisher'){Object.assign(publisherState,{query:'',corpus:'all',model:'all',page:1});document.querySelector('#publisher-texts').outerHTML=publisherView();document.querySelector('#publisher-query').focus();announce('Publisher filters cleared.');}if(e.target.id==='export-publisher')exportPublisher();});
